import{_ as i,l,o as a,c as s,v as r,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"函数式队列","description":"","frontmatter":{"title":"函数式队列","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/functional-queue.md","filePath":"cs/functional-queue.md","lastUpdated":1789023840000}'),u={name:"cs/functional-queue.md"};function h(f,e,_,m,k,E){const t=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="函数式队列" tabindex="-1">函数式队列 <a class="header-anchor" href="#函数式队列" aria-label="Permalink to &quot;函数式队列&quot;">​</a></h1><div class="epigraph"><p>前栈出队、后栈入队；后栈倒进前栈时一次线性，摊还仍 $O(1)$。旧版本的两栈指针保持持久。</p><footer>—— 据 Okasaki, Simple and Efficient Purely Functional Queues and Deques, JFP 1995；Okasaki, Purely Functional Data Structures；Hood and Melville 整理</footer></div><p><a href="/cs/persistent-path-copy">上一课</a> 给了树的复制。<a href="/cs/deque">双端队列</a> 与<a href="/cs/amortized-analysis">摊还</a> 在命令式数组上已出现。函数式不能原地改链表头尾而不影响旧版本。本课不旋转 BST。缺口是双列表队列：<code>front</code> 与 <code>rear</code>（rear 逆序存），倒栈维持平衡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单链表：入队若只改尾，旧版本的尾无法共享地接上新节点而不改变旧队列。入队全在头则 FIFO 变 LIFO。Hood–Melville / Okasaki：维护两个列表 \\(f,r\\)，不变量常 \\(|r|\\le|f|\\)（变体多）。入队：cons 到 \\(r\\)。出队：从 \\(f\\) 头拿；若 \\(f\\) 空则 reverse \\(r\\) 成新 \\(f\\)。缺口是<strong>倒栈次数被长度摊还</strong>，且每次操作返回新对 \\((f&#39;,r&#39;)\\)，旧对仍可用。</p><p><span class="marginnote">Okasaki <em>JFP</em> 1995 与专著。惰性流可把 reverse 渐进执行，最坏也 \\(O(1)\\) 步（更细）。本课先钉摊还双栈。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>snoc(x)</code>：<code>(f, x::r)</code>，若违不变量则 <code>rotate</code>。<code>head</code>/<code>tail</code> 走 \\(f\\)。持久：cons 共享前缀，reverse 产生新链，旧 \\(r\\) 仍在。</p>',8)),(a(),n(p,null,{default:o(()=>[c(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20ENQ%5B%22%E5%85%A5%E9%98%9F%22%5D%20--%3E%20REAR%5B%22rear%20%E6%A0%88%22%5D%0A%20%20DEQ%5B%22%E5%87%BA%E9%98%9F%22%5D%20--%3E%20FRONT%5B%22front%20%E6%A0%88%22%5D%0A%20%20REV%5B%22rear%20%E5%80%92%E5%85%A5%20front%22%5D%20--%3E%20AM%5B%22%E6%91%8A%E8%BF%98%20O(1)%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 Michael–Scott 无锁队列：那是命令式共享内存；本课不可变。与 Rope：Rope 是随机访问序列，队列只端点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>势能 \\(|r|\\) 或类似，倒栈花 \\(\\Theta(|r|)\\) 时势能下降。实时变体用惰性，避免单次峰值——若实时路径不能倒整个 \\(r\\)，用 Okasaki 的流。不要用函数式队列当高性能 SPSC 环（那是数组 + 原子）。</p><p>下一课缓存无关：换的是递归布局与 I/O 模型，不必持久。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把实时 deque 的全部旋转写完。无锁进度是后课 CAS 队列。磁盘 B 树的缓存有关分析与 cache-oblivious 对偶，下一课。</p><p>后课默认：持久 FIFO 用双栈/惰性队列。最优缓存利用不依赖 \\(B\\) 参数的结构，用缓存无关模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>函数式队列：两栈，倒栈摊还 \\(O(1)\\)，版本共享。</li><li>惰性可消峰值。</li><li>下一课 I/O 与递归布局。</li><li>出处：Okasaki, <em>JFP</em>, 1995 与专著；Hood and Melville。</li></ul>',9))])}const P=i(u,[["render",h]]);export{q as __pageData,P as default};
